USE referral_platform;

-- Module 9: indexes support the equality/range predicates used by the search screens.
SET @sql = IF((SELECT COUNT(*) FROM information_schema.statistics WHERE table_schema = DATABASE() AND table_name = 'customer_referrals' AND index_name = 'customer_referrals_business_status_submitted_index') = 0, 'CREATE INDEX customer_referrals_business_status_submitted_index ON customer_referrals (business_id, status, submitted_at)', 'SELECT 1'); PREPARE module9_stmt FROM @sql; EXECUTE module9_stmt; DEALLOCATE PREPARE module9_stmt;
