SET @sql = IF((SELECT COUNT(*) FROM information_schema.statistics WHERE table_schema = DATABASE() AND table_name = 'referral_opportunities' AND index_name = 'referral_opportunities_business_status_created_index') = 0, 'CREATE INDEX referral_opportunities_business_status_created_index ON referral_opportunities (business_id, status, created_at)', 'SELECT 1'); PREPARE module9_stmt FROM @sql; EXECUTE module9_stmt; DEALLOCATE PREPARE module9_stmt;
